再看利用子类构造函数转发的情况：#include&lt;bits&#x2F;stdc++.h&gt;
using namespace std;
class Base {
public:
int m_a&#x3D;0;
string m_b&#x3D;”\0”;
char m_c &#x3D; ‘0’;
Base(int a,string b,char c) {&#x2F;&#x2F;父类的构造函数
m_a &#x3D; a;
m_b &#x3D; b;
m_c &#x3D; c;
}
};
class Son:public Base {
public:
int m_a&#x3D;0;
string m_b &#x3D; “\0”;
Son(int num,string str) :Base(-1, str,’a’) {&#x2F;&#x2F;这个子类的构造函数 实现了自身的构造 并调用了父类的含参构造 而不再是默认构造了
&#x2F;&#x2F;第一个形参列表给子类构造用 ：后的第二个形参列表给父类构造用
m_a &#x3D; num;
m_b &#x3D; str;
}
void func() {
cout &lt;&lt;”子类自身构造的成员信息:       “&lt;&lt; m_a &lt;&lt; “ “ &lt;&lt; m_b&lt;&lt;endl;
cout &lt;&lt; “继承父类的成员信息:       “ &lt;&lt; Base::m_a &lt;&lt; “ “ &lt;&lt; Base::m_b &lt;&lt;” “&lt;&lt; Base::m_c;
printf(“\n\n\n”);
}
};
int main() {
Son son(42,”奇妙小信息”); son.func();
}

